function m(n,t){switch(n){case"Last Minute":return 6e4;case"Last 5 Minutes":return 5*6e4;case"Last 30 Minutes":return 30*6e4;case"day":return Math.max(0,t)*24*60*6e4;case"hour":return Math.max(0,t)*60*6e4;case"minute":return Math.max(0,t)*6e4;case"second":return Math.max(0,t)*1e3;default:return 0}}var _=[{ms:1440*6e4,one:"day",many:"days"},{ms:60*6e4,one:"h",many:"h"},{ms:6e4,one:"min",many:"min"},{ms:1e3,one:"s",many:"s"}];function u(n,t){let e=m(n,t);if(e<=0)return"";let a=c(e),s=a.smoothingPeriod*a.sampleTime;for(let o of _){if(s<o.ms)continue;let r=Math.round(s/o.ms*10)/10;return`${r} ${r===1?o.one:o.many}`}return`${Math.round(s)} ms`}function c(n){let t=n>0?Math.max(100,Math.round(n/500)):1e3,e=Math.max(1,Math.ceil(n/t)),a=Math.max(1,Math.floor(e*.25));return{sampleTime:Math.max(1,t),maxDataPoints:e,smoothingPeriod:a}}export{m as a,u as b,c};
